NCCL API
Send/receive with NCCL


…
// Initialized NCCL communicator

int N=16;
cudaStream_t stream;                                                                                                                                           Creating GPU stream for NCCL stream
cudaStreamCreate(&stream);
if (rank == 0) {
  ncclSend(send_buf, N, ncclInt, 1, nccl_comm, stream);                                                                                          Sending 16 * ncclInt to rank 1 as part of nccl_comm
} else if (rank == 1) {
  ncclRecv(recv_buf, N, ncclInt, 0, nccl_comm, stream);
}

cudaStreamSynchronize(stream);

// Destroy NCCL communicator
…




