NCCL Device API
                                                                                                                              __global__ kernel(ncclDevComm_t devComm, ncclWindow_t win) {


In-kernel communication toolbox                                                                                                    float* ptr = ncclGetPeerPointer(devComm, offset, peer);
                                                                                                                                   ptr[0] = value;

                                                                                                                                   ncclBarrierSession bar { ncclCoopCta(), ncclTeamTagLsa(),
                             Remote memory access                                                                                                           devComm, blockIdx.x };
              LSA            →Get pointer for remote memory                                                                        bar.sync(ncclCoopCta(), cuda::memory_order_release);
                             →Perform normal memory operations to pointer
        Load/Store
                             Synchronization
        Accessible           → LSA barrier                                                                                         float* ptr = ncclGetLsaMultimemPointer(win, offset, devComm);
                                                                                                                                   value = multimem_reduce_sum(ptr);
                                                                                                                                   multimem_store(ptr, value);
                             NVLink SHARP access
         Multimem            →Get pointer to multimem mappings
                             → Perform multimem operations on pointer                                                              ncclGin gin { devComm, blockIdx.x % devComm.ginContextCount };
                                                                                                                                   gin.put(ncclTeamWorld(devComm), peer,
      NVLink SHARP           Synchronization                                                                                               win, remoteOffset, win, localOffset,
                                                                                                                                           size, ncclGin_SignalInc{signalIndex});
                             → LSA barrier with Multimem scope
                                                                                                                                   gin.waitSignal(ncclCoopCta(), signalIndex, signalValue);

                             Remote memory access
                                                                                                                                   ncclBarrierSession bar {
              GIN            →Create GIN object, select GIN context
                                                                                                                                       ncclCoopCta(), ncclTeamTagWorld(), gin, blockIdx.x };
                             →Perform put() operations                                                                             bar.sync(ncclCoopCta(), cuda::memory_order_relaxed,
                             →Wait on signals for remote operations                                                                    ncclGinFenceLevel::relaxed);
       GPU-Initiated         →Wait on counters for local operations
        Networking           Synchronization                                                                                  }
                             →GIN barrier


